/* employees.sql */

-- base employees table for EBR demo
CREATE SEQUENCE employees_seq
 START WITH     207
 INCREMENT BY   1
 NOCACHE
 NOCYCLE;

CREATE TABLE employees
   (EMPLOYEE_ID    NUMBER(6,0) DEFAULT employees_seq.NEXTVAL 
        CONSTRAINT employees_pk PRIMARY KEY, 
    EMPLOYEE_CODE  VARCHAR2(20 BYTE),
	FIRST_NAME     VARCHAR2(20 BYTE), 
	LAST_NAME      VARCHAR2(25 BYTE) CONSTRAINT EMP_LAST_NAME_NN NOT NULL ENABLE, 
	EMAIL          VARCHAR2(25 BYTE) CONSTRAINT EMP_EMAIL_NN NOT NULL ENABLE, 
	PHONE_NUMBER   VARCHAR2(20 BYTE), 
	HIRE_DATE      DATE CONSTRAINT EMP_HIRE_DATE_NN NOT NULL ENABLE, 
	JOB_NAME       VARCHAR2(40 BYTE),
	SALARY         NUMBER(8,2), 
	COMMISSION_PCT NUMBER(2,2)
   ) 
  TABLESPACE USERS ;



REM INSERTING into HR.employees
SET DEFINE OFF;

COMMIT;
